using System.Text.Json;
using Midnight.Shared.Http;

namespace Midnight.Daemon.Core.Configuration;

/// <summary>Daemon configuration, stored in /etc/midnight/config.json and generated by the panel setup page</summary>
public class DaemonConfiguration
{
    public const string DefaultPath = "/etc/midnight/config.json";

    public string PanelUrl { get; set; } = "http://localhost:5220";

    public string TokenId { get; set; } = "";

    /// <summary>Node token used for panel &lt;-&gt; daemon requests and to verify browser websocket tokens. Never logged.</summary>
    public string Token { get; set; } = "";

    public int HttpPort { get; set; } = 8080;
    public int SftpPort { get; set; } = 2022;

    public string DataPath { get; set; } = "/var/lib/midnight";

    /// <summary>Docker engine endpoint, e.g. unix:///var/run/docker.sock</summary>
    public string DockerSocket { get; set; } = "unix:///var/run/docker.sock";

    public SslConfiguration Ssl { get; set; } = new();

    public static DaemonConfiguration Load(string path)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException($"Daemon configuration not found at '{path}'. Copy it from the node setup page in the panel.", path);

        return JsonSerializer.Deserialize<DaemonConfiguration>(File.ReadAllText(path), JsonDefaults.Options)
               ?? throw new InvalidOperationException($"Daemon configuration at '{path}' is empty");
    }

    /// <summary>Returns a list of problems that prevent the daemon from starting</summary>
    public List<string> Validate()
    {
        var errors = new List<string>();

        if (!Uri.TryCreate(PanelUrl, UriKind.Absolute, out var panelUri) || (panelUri.Scheme != "http" && panelUri.Scheme != "https"))
            errors.Add("PanelUrl must be an absolute http(s) url");

        if (string.IsNullOrWhiteSpace(TokenId) || string.IsNullOrWhiteSpace(Token))
            errors.Add("TokenId and Token are required");

        if (HttpPort is < 1 or > 65535)
            errors.Add("HttpPort must be between 1 and 65535");

        if (SftpPort is < 1 or > 65535)
            errors.Add("SftpPort must be between 1 and 65535");

        if (string.IsNullOrWhiteSpace(DataPath) || !Path.IsPathRooted(DataPath))
            errors.Add("DataPath must be an absolute path");

        if (!Uri.TryCreate(DockerSocket, UriKind.Absolute, out _))
            errors.Add("DockerSocket must be an absolute uri like unix:///var/run/docker.sock");

        if (Ssl.Enabled && (string.IsNullOrWhiteSpace(Ssl.CertificatePath) || string.IsNullOrWhiteSpace(Ssl.KeyPath)))
            errors.Add("Ssl.CertificatePath and Ssl.KeyPath are required when ssl is enabled");

        return errors;
    }
}

public class SslConfiguration
{
    public bool Enabled { get; set; }
    public string CertificatePath { get; set; } = "";
    public string KeyPath { get; set; } = "";
}
